def binary_search(arr, target):
    low, high = 0, len(arr) - 1
    while low < high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)
